    edges = 0
    adj = {}
    for c, target in mapping.items():
        if c != target:
            edges += 1
            adj[c] = target

    # Calculate in-degrees for the induced subgraph of nodes that need to be changed
    in_degree = {k: 0 for k in adj}
    for k, v in adj.items():
        if v in in_degree:
            in_degree[v] += 1

    # Traverse from all nodes with in-degree 0 to mark nodes that are NOT part of a pure cycle
    visited = set()
    for k, deg in in_degree.items():
        if deg == 0:
            curr = k
            while curr in adj and curr not in visited:
                visited.add(curr)
                curr = adj[curr]

    # Count the number of pure cycles among the remaining unvisited nodes
    pure_cycles = 0
    for node in adj:
        if node not in visited:
            curr = node
            while curr not in visited:
                visited.add(curr)
                curr = adj[curr]
            pure_cycles += 1

    # Minimum operations = (number of transition edges) + (number of pure cycles to break)
    print(edges + pure_cycles)

